import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'risk' | 'paused' | 'done';

type Project = {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
};

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'info' | 'alt' }
> = {
  active: { label: 'Активен', tone: 'success' },
  risk: { label: 'Под риском', tone: 'warning' },
  paused: { label: 'На паузе', tone: 'info' },
  done: { label: 'Завершён', tone: 'alt' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'risk', 'paused', 'done'];

const PROJECTS: Project[] = [
  { id: 'p-1', name: 'Платёжный шлюз', quota: 82, status: 'active' },
  { id: 'p-2', name: 'Мобильное приложение', quota: 96, status: 'risk' },
  { id: 'p-3', name: 'Аналитика событий', quota: 41, status: 'active' },
  { id: 'p-4', name: 'Миграция хранилища', quota: 67, status: 'paused' },
  { id: 'p-5', name: 'Портал партнёров', quota: 23, status: 'done' },
  { id: 'p-6', name: 'Рекомендательный сервис', quota: 88, status: 'risk' },
  { id: 'p-7', name: 'Внутренний биллинг', quota: 54, status: 'active' },
  { id: 'p-8', name: 'Поиск по документам', quota: 12, status: 'paused' },
  { id: 'p-9', name: 'Обновление дизайн-системы', quota: 75, status: 'active' },
  { id: 'p-10', name: 'Архив отчётов', quota: 99, status: 'done' },
  { id: 'p-11', name: 'Очередь уведомлений', quota: 36, status: 'risk' },
  { id: 'p-12', name: 'Сегментация клиентов', quota: 61, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(['active', 'risk']);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () =>
      statuses.length === 0
        ? PROJECTS
        : PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses([]);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        maxWidth: '720px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)' }}>Расход по проектам</h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)' }}>
          Найдено проектов: {filtered.length}
        </p>
      </header>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_ORDER.map((status) => {
          const selected = statuses.includes(status);
          return (
            <JxChip
              key={status}
              active={selected}
              removable={selected}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      <JxDivider />

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные статусы не подходит ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 14px',
                  background: 'var(--jx-surface-2)',
                  border: '1px solid var(--jx-rule)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle value={project.quota} showValue />
                <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', flex: 1 }}>
                  <span>{project.name}</span>
                  <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-mono)' }}>
                    квота израсходована на {project.quota}%
                  </span>
                </div>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </div>
      )}
    </section>
  );
}

